-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "推荐"
L["rm.mop.deathknight.blood.Description"] = "推荐鲜血坦克使用，在鲜血专精中选用。从远处用爆发、冰冷触摸或死亡之握拉怪。生命值低于一半时、鲜血护盾缺失时（80 级起）以及四个冰霜和邪恶符文全部充满之前使用灵界打击；符文能量接近 90 时使用符文打击（学会前为 80 时使用凋零缠绕）；用爆发（否则冰冷触摸和暗影打击）施加疾病，68 级起用血液沸腾刷新疾病；低于 35% 时使用灵魂收割；两个鲜血符文时使用心脏打击（60 级前为鲜血打击）；疾病持续期间赤色天灾触发时使用枯萎凋零，否则使用血液沸腾；活力分流达到十一层时使用它；然后是灵界打击、心脏打击、符文打击和寒冬号角。三个敌人攻击你时：枯萎凋零，扩散疾病（有动荡之血时用血液沸腾，否则用传染）和血液沸腾。提醒：没有灵气时使用鲜血灵气、白骨之盾、寒冬号角、心灵冰冻，根据你的生命值使用符文分流、吸血鬼之血、冰封之韧、符文武器增效和天灾契约，对精英使用符文刃舞，组队首领战前使用亡者大军。它无法看到即将到来的伤害，因此反魔法护罩（关闭）和大型防御技能由你掌控。"
L["rm.mop.deathknight.blood.simulator.Name"] = "按生命值反应（模拟器）"
L["rm.mop.deathknight.blood.simulator.Description"] = "作为推荐鲜血内置循环的替代，适合有治疗者配合的团队坦克，默认关闭：启用它并禁用那个，或提高它的优先级。灵界打击仅在生命值低于 70%、鲜血护盾缺失或即将消失，或冰霜和邪恶符文即将溢出前使用，而不是每有符文就用；冰霜和邪恶符文还要一秒以上才就绪时，单独的鲜血符文用于心脏打击。它没有范围伤害部分，提醒与推荐的循环相同。"
L["rm.mop.deathknight.frost.Name"] = "双手武器"
L["rm.mop.deathknight.frost.Description"] = "使用双手武器的冰霜，这是常见的升级配置；在冰霜专精中，只要双持内置循环不适用就会选用。开场、疾病、生存和范围伤害与双持内置循环相同，然后杀戮机器触发时使用湮没，符文能量高于 76 时使用冰霜打击，白霜触发时使用凛风冲击，任意一对符文充满时使用湮没，湮没，凛风冲击，吸血瘟疫，40 点时使用冰霜打击，以及寒冬号角。学会湮没（58 级）之前，用灵界打击消耗你的邪恶符文。提醒与双持内置循环相同。"
L["rm.mop.deathknight.frost.dualwield.Name"] = "双持"
L["rm.mop.deathknight.frost.dualwield.Description"] = "推荐使用两把单手武器的冰霜（精通冰流派，Masterfrost）使用；在冰霜专精中，当你的副手持有武器时选用。以爆发或凛风冲击拉怪（单刷时用死亡之握）。黑暗援助触发或生命值低于 35% 时使用灵界打击，活力分流达到十一层时使用它，施加疾病（邪恶虫群、爆发、凛风冲击、暗影打击），低于 35% 时使用灵魂收割，杀戮机器触发或符文能量高于 89 时使用冰霜打击，白霜触发或两个冰霜符文或两个死亡符文都就绪时使用凛风冲击，符文能量低于 77 时用两个邪恶符文施放湮没，符文能量高于 76 时使用冰霜打击，湮没，凛风冲击，爆发就绪时在疾病消失前使用吸血瘟疫，40 点时使用冰霜打击，寒冬号角。三个敌人攻击你时：扩散疾病、枯萎凋零和凛风冲击。提醒：冰霜灵气、冰霜之柱、亡者复生、所有符文都用完时使用符文武器增效、寒冬号角、心灵冰冻、生命值低时使用冰封之韧和天灾契约、组队首领战前使用亡者大军。"
L["rm.mop.deathknight.unholy.Name"] = "邪恶"
L["rm.mop.deathknight.unholy.Description"] = "推荐邪恶专精使用，也是鲜血和冰霜都不适用的死亡骑士（包括没有专精的）的内置循环。从远处用爆发或冰冷触摸拉怪（单刷时用死亡之握）。黑暗援助触发或生命值低于 35% 时使用灵界打击，施加疾病（邪恶虫群、爆发、暗影打击、冰冷触摸），活力分流达到十一层时使用它，低于 35% 时使用灵魂收割，暗影灌注达到五层时使用黑暗突变，符文能量接近上限时使用凋零缠绕，对能存活较久的目标使用枯萎凋零，天灾打击，末日突降触发或 40 点时使用凋零缠绕，不洁之力生效时使用爆发，脓疮打击（学会前为鲜血打击），吸血瘟疫，寒冬号角。三个敌人攻击你时：扩散疾病、枯萎凋零、血液沸腾，以及用冰霜符文施放冰冷触摸。提醒：邪恶灵气、你的食尸鬼、嗜血期间或长时间的精英战斗中使用召唤石像鬼、邪恶狂热、符文武器增效、寒冬号角、心灵冰冻、生命值低时使用冰封之韧和天灾契约、组队首领战前使用亡者大军；反魔法护罩为关闭状态。"
L["rm.mop.deathknight.unholy.simulator.Name"] = "邪恶，符文溢出前攒资源（模拟器）"
L["rm.mop.deathknight.unholy.simulator.Description"] = "作为推荐邪恶内置循环的替代，按照模拟器、wowtbc.gg、Method 和 MaxDps 的打法；默认关闭：启用它并禁用那个，或提高它的优先级。黑暗突变未生效时，凋零缠绕用于重新叠加暗影灌注；两个邪恶符文或两个死亡符文都就绪时，天灾打击优先；两个鲜血符文和两个冰霜符文都就绪时，脓疮打击优先；其余开场、疾病、范围伤害和提醒与推荐的循环相同。"
L["rm.retail.deathknight.blood.Name"] = "暴雪战斗辅助"
L["rm.retail.deathknight.blood.Description"] = "推荐鲜血专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的吸血鬼之血和亡者复生、对可打断的施法使用心灵冰冻，以及你的种族冷却技能和战斗中一就绪就使用的冰封之韧。敌人的施法在战斗中是隐藏的，因此心灵冰冻只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用冰封之韧由你自己决定。主动减伤的时机、反魔法护罩、嘲讽和饰品仍由你自己掌控。"
L["rm.retail.deathknight.blood.guide.Name"] = "参考（Icy Veins 和 Wowhead）"
L["rm.retail.deathknight.blood.guide.Description"] = "仅供参考，默认关闭：指南中的鲜血优先级。在至暗之夜的战斗中，你的增益效果和目标的减益效果对插件隐藏，因此读取它们的步骤在战斗中会等待；可以阅读它，或复制后自行试验。生命值和符文能量在正式服中是隐藏的，因此只要负担得起就会使用灵界打击。以死神的抚摩拉怪。灵界打击；白骨之盾缺失、少于五层、即将结束或破灭生效时使用精髓分裂（不在近战范围时改用死神的抚摩）；萨莱因之赐期间，灵界打击，使用一次血液沸腾，赤色天灾触发时使用枯萎凋零，以及心脏打击；赤色天灾触发或面对四个敌人时使用枯萎凋零；吸血鬼打击；吞噬；沸点触发、血之疫病缺失或充能已满时使用血液沸腾；心脏打击。提醒：亡者复生、吸血鬼之血、死神印记、在死神印记之后使用符文刃舞，以及战斗辅助内置循环中的功能性提醒。"
L["rm.retail.deathknight.blood.simc.Name"] = "死亡使者参考（SimulationCraft）"
L["rm.retail.deathknight.blood.simc.Description"] = "仅供参考，默认关闭：SimulationCraft 的死亡使者列表，会把符文能量花在灵界打击上来造成伤害。战斗数据被隐藏，因此它无法在至暗之夜的战斗中运行，而且符文能量在正式服中是隐藏的，所以没有溢出上限时的消耗。枯萎凋零未生效时随时使用，死神印记，破灭生效时使用精髓分裂，符文不足时用死神的抚摩维持白骨之盾（否则使用精髓分裂），灵界打击，血液沸腾，符文刃舞之外使用吞噬，心脏打击。提醒：亡者复生、符文刃舞、吸血鬼之血以及功能性提醒。"
L["rm.retail.deathknight.frost.Name"] = "暴雪战斗辅助"
L["rm.retail.deathknight.frost.Description"] = "推荐冰霜专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的冰龙吐息和亡者复生、对可打断的施法使用心灵冰冻，以及你的种族冷却技能和战斗中一就绪就使用的冰封之韧。敌人的施法在战斗中是隐藏的，因此心灵冰冻只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用冰封之韧由你自己决定。"
L["rm.retail.deathknight.frost.guide.Name"] = "参考（Icy Veins 和 SimulationCraft）"
L["rm.retail.deathknight.frost.guide.Description"] = "仅供参考，默认关闭：指南中的冰霜优先级。杀戮机器、白霜和锋锐之霜在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行；符文能量在正式服中是隐藏的，所以没有溢出上限检查。拥有两层杀戮机器，或一层杀戮机器且有三个符文时使用湮灭，有破碎之刃时在锋锐之霜叠满五层时使用冰霜打击，白霜触发时使用凛风冲击，杀戮机器触发时使用湮灭，冰霜打击，湮灭；三个或更多敌人时换用冰霜之镰和冰川突进；不在近战范围时使用凛风冲击。提醒：冷酷严冬、冰霜之柱、在冰霜之柱期间使用冰龙吐息和冰霜巨龙之怒、死神印记、亡者复生、在两层充能时使用符文武器增效，以及功能性提醒。"
L["rm.retail.deathknight.frost.wowhead.Name"] = "参考（Wowhead）"
L["rm.retail.deathknight.frost.wowhead.Description"] = "仅供参考，默认关闭：Wowhead 的冰霜施放顺序，把冷却技能也排进了循环。战斗数据被隐藏，因此它无法在至暗之夜的战斗中运行；符文能量在正式服中是隐藏的，所以没有溢出上限检查。两层充能时使用符文武器增效，死神印记，冰霜之柱，冰龙吐息，冰霜巨龙之怒；然后拥有两层杀戮机器，或一层杀戮机器且破灭生效时使用湮灭，白霜触发时使用凛风冲击，杀戮机器触发时使用湮灭，使用符文武器增效获得新的杀戮机器，冰霜打击，湮灭，凛风冲击。三个或更多敌人时换用冰霜之镰和冰川突进。"
L["rm.retail.deathknight.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.deathknight.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是死亡骑士的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有死亡骑士内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.deathknight.unholy.Name"] = "暴雪战斗辅助"
L["rm.retail.deathknight.unholy.Description"] = "推荐邪恶专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议（它会自行召唤食尸鬼，并自行使用亡者大军和黑暗突变）；你施法或引导时它会等待。同时提醒：对可打断的施法使用心灵冰冻，以及你的种族冷却技能和战斗中一就绪就使用的冰封之韧。敌人的施法在战斗中是隐藏的，因此心灵冰冻只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用冰封之韧由你自己决定。"
L["rm.retail.deathknight.unholy.guide.Name"] = "参考（Icy Veins 和 Wowhead）"
L["rm.retail.deathknight.unholy.guide.Description"] = "仅供参考，默认关闭：指南中的邪恶优先级。触发效果和疫病在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行；符文能量和目标的生命值在正式服中是隐藏的，所以斩杀阶段和萨莱因的符文能量消耗被省略了。没有食尸鬼时使用亡者复生；使用脓疮毒镰保持其疫病带来的急速；割魂索命触发时使用灵魂收割；黑暗突变期间使用腐化；末日突降或禁断知识触发时使用凋零缠绕（四个或更多敌人时改用扩散）；没有次级食尸鬼充能时使用脓疮打击，有充能时使用天灾打击；凋零缠绕。提醒：亡者大军、黑暗突变、疫病缺失时使用爆发，以及功能性提醒。"
L["rm.retail.deathknight.unholy.simc.Name"] = "参考（SimulationCraft）"
L["rm.retail.deathknight.unholy.simc.Description"] = "仅供参考，默认关闭：SimulationCraft 的邪恶列表，使用凋零缠绕的频率要高得多。战斗数据被隐藏，因此它无法在至暗之夜的战斗中运行；符文能量和目标生命值在正式服中是隐藏的，所以上限检查和斩杀检查被省略了。维持脓疮毒镰，黑暗突变期间使用灵魂收割，末日突降触发时使用凋零缠绕，黑暗突变期间使用腐化，黑暗突变或禁断知识期间，以及亡者大军还有 5 秒以上才就绪时使用凋零缠绕，有次级食尸鬼充能时使用天灾打击，脓疮打击。三个或更多敌人时：用扩散代替凋零缠绕，次级食尸鬼充能少于三层时使用脓疮打击。提醒：爆发、对成群敌人使用枯萎凋零、亡者大军、黑暗突变。"
